// Trata a resposta da IA e calcula o SLA
const raw = $input.first().json;
let texto = '';
try { texto = raw.content.map(b => b.text || '').join('').trim(); } catch (e) { texto = ''; }
texto = texto.replace(/```json/gi, '').replace(/```/g, '').trim();
let d;
try { d = JSON.parse(texto); } catch (e) {
  d = { category: 'outro', urgency: 'normal', summary: 'IA não devolveu JSON válido — rever manualmente.', contact_name: null, draft: null };
}
// Offsets de SLA por categoria (em horas). spam = sem SLA.
const slaHoras = {
  pedido_orcamento: 4, reclamacao: 2, followup_cliente: 8, compra_cliente: 4,
  compra_fornecedor: 24, fornecedor_sourcing: 72, tabela_precos_fornecedor: 72,
  fatura_administrativo: 48, outro: 24
};
const orig = $('Normalizar campos').first().json;
const base = orig.receivedAt ? new Date(orig.receivedAt) : new Date();
let sla_due_at = null;
if (d.category !== 'spam' && slaHoras[d.category] != null) {
  sla_due_at = new Date(base.getTime() + slaHoras[d.category] * 3600 * 1000).toISOString();
}
// Categorias que exigem rascunho/resposta humana
const exigeResposta = ['pedido_orcamento','followup_cliente','reclamacao','compra_cliente'].includes(d.category);
return [{ json: { ...orig, ...d, sla_due_at, exigeResposta } }];

